\section{Proof of Proposition~\ref{prop:attn_mismatch}}
\label{Aprop:distribution_alignment}
\begin{proof}
Fix a query position $t$ and its preceding context. Running the same model with
full and sparse attention at inference yields two next-token distributions over
the vocabulary, $p^{\mathrm{full}}_\theta(t)$ and $p^{\mathrm{sparse}}_\theta(t)$.
Let $y$ denote a token drawn from $p^{\mathrm{full}}_\theta(t)$, and let
$\mathbb{E}_{\mathrm{full}}[\cdot]$ denote the expectation over
$y\sim p^{\mathrm{full}}_\theta(t)$. The expectation is taken under $p^{\mathrm{full}}_\theta(\cdot\mid t)$, the
model's full-attention distribution, since we measure the drift of sparse
inference relative to this reference; this is precisely the choice under which
the cross-entropy gap equals a KL divergence. With this convention, the entropy of the
full-attention distribution and its cross-entropy relative to the
sparse-attention distribution are
\begin{align}
H\!\big(p^{\mathrm{full}}_\theta(t)\big)
  &= \mathbb{E}_{\mathrm{full}}\big[-\log p^{\mathrm{full}}_\theta(y)\big], \nonumber\\
H\!\big(p^{\mathrm{full}}_\theta(t),\, p^{\mathrm{sparse}}_\theta(t)\big)
  &= \mathbb{E}_{\mathrm{full}}\big[-\log p^{\mathrm{sparse}}_\theta(y)\big]. \nonumber
\end{align}
Both expectations are taken over the \emph{same} distribution
$p^{\mathrm{full}}_\theta(t)$, conditioned on the same context. By the definition
of the KL divergence,
\begin{align}
D_{\mathrm{KL}}\!\big(p^{\mathrm{full}}_\theta(t)\,\big\|\,p^{\mathrm{sparse}}_\theta(t)\big)
  &= \mathbb{E}_{\mathrm{full}}\!\left[\log \frac{p^{\mathrm{full}}_\theta(y)}{p^{\mathrm{sparse}}_\theta(y)}\right] \nonumber\\
  &= \mathbb{E}_{\mathrm{full}}\big[-\log p^{\mathrm{sparse}}_\theta(y)\big]
     - \mathbb{E}_{\mathrm{full}}\big[-\log p^{\mathrm{full}}_\theta(y)\big] \nonumber\\
  &= H\!\big(p^{\mathrm{full}}_\theta(t),\, p^{\mathrm{sparse}}_\theta(t)\big)
     - H\!\big(p^{\mathrm{full}}_\theta(t)\big). \nonumber
\end{align}
Rearranging yields the claim:
\begin{equation}
H\!\big(p^{\mathrm{full}}_\theta(t),\, p^{\mathrm{sparse}}_\theta(t)\big)
  = H\!\big(p^{\mathrm{full}}_\theta(t)\big)
  + D_{\mathrm{KL}}\!\big(p^{\mathrm{full}}_\theta(t)\,\big\|\,p^{\mathrm{sparse}}_\theta(t)\big). \nonumber
\end{equation}
\end{proof}

\section{Proof of Theorem~\ref{thm:error_decomposition}}
\label{app:proof_of_error_decomposition}
\begin{proof}
We decompose the full attention output into contributions from selected tokens $\mathcal{S}(t)$ and dropped tokens $\mathcal{S}^c(t)$:
\begin{equation}
h^{\mathrm{full}}(t) = \sum_{j \in \mathcal{S}(t)} a^{\mathrm{full}}(t,j) v(j) + \sum_{j \in \mathcal{S}^c(t)} a^{\mathrm{full}}(t,j) v(j).
\label{eq:app_decomp}
\end{equation}
For any token $j \in \mathcal{S}(t)$, the full and sparse attention weights are related by:
\begin{equation}
a^{\mathrm{full}}(t,j) = \frac{\exp(s(t,j))}{\sum_{k < t} \exp(s(t,k))}, \quad a^{\mathrm{sparse}}(t,j) = \frac{\exp(s(t,j))}{\sum_{k \in \mathcal{S}(t)} \exp(s(t,k))}, \nonumber
\end{equation}
where $s(t,j)$ denotes the unnormalized attention score from query position $t$ to key position $j$. Their ratio yields:
\begin{equation}
\frac{a^{\mathrm{full}}(t,j)}{a^{\mathrm{sparse}}(t,j)} = \frac{\sum_{k \in \mathcal{S}(t)} \exp(s(t,k))}{\sum_{k < t} \exp(s(t,k))} = 1 - \delta(t), \nonumber
\end{equation}
where $\delta(t) = \sum_{j \in \mathcal{S}^c(t)} a^{\mathrm{full}}(t,j)$ is the dropped attention mass. Thus, for any $j \in \mathcal{S}(t)$:
\begin{equation}
a^{\mathrm{full}}(t,j) = (1 - \delta(t)) \, a^{\mathrm{sparse}}(t,j).
\label{eq:app_renorm}
\end{equation}
Substituting Eq.~\eqref{eq:app_renorm} into the first term of Eq.~\eqref{eq:app_decomp}:
\begin{equation}
\sum_{j \in \mathcal{S}(t)} a^{\mathrm{full}}(t,j) v(j) = (1 - \delta(t)) \sum_{j \in \mathcal{S}(t)} a^{\mathrm{sparse}}(t,j) v(j) = (1 - \delta(t)) \, h^{\mathrm{sparse}}(t). \nonumber
\end{equation}
Substituting back into Eq.~\eqref{eq:app_decomp} and rearranging:
\begin{equation}
h^{\mathrm{full}}(t) - h^{\mathrm{sparse}}(t) = \sum_{j \in \mathcal{S}^c(t)} a^{\mathrm{full}}(t,j) v(j) - \delta(t) \, h^{\mathrm{sparse}}(t). \nonumber
\end{equation}
Taking norms and applying the triangle inequality:
\begin{equation}
\|h^{\mathrm{full}}(t) - h^{\mathrm{sparse}}(t)\| \leq \left\| \sum_{j \in \mathcal{S}^c(t)} a^{\mathrm{full}}(t,j) v(j) \right\| + \delta(t) \|h^{\mathrm{sparse}}(t)\|.
\label{eq:app_triangle}
\end{equation}
For the first term, applying the triangle inequality and using the non-negativity of attention weights:
\begin{equation}
\left\| \sum_{j \in \mathcal{S}^c(t)} a^{\mathrm{full}}(t,j) v(j) \right\| \leq \sum_{j \in \mathcal{S}^c(t)} a^{\mathrm{full}}(t,j) \|v(j)\| \leq \delta(t) \max_{j \in \mathcal{S}^c(t)} \|v(j)\|. \nonumber
\end{equation}
Substituting into Eq.~\eqref{eq:app_triangle} and factoring out $\delta(t)$ yields the result:
\begin{equation}
\|h^{\mathrm{full}}(t) - h^{\mathrm{sparse}}(t)\| \leq \delta(t) \left( \max_{j \in \mathcal{S}^c(t)} \|v(j)\| + \|h^{\mathrm{sparse}}(t)\| \right). \nonumber
\end{equation}
\end{proof}



